// Register.jsx
import React, { useState } from "react";
import { createUserWithEmailAndPassword, updateProfile, signOut } from "firebase/auth";
import { auth, db } from "../js/firebaseConfig";
import { doc, setDoc, serverTimestamp } from "firebase/firestore";

import { uploadAvatar } from "../js/supabaseUpload"; // <-- NOVO

export default function Register({ setScreen }) {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [senha2, setSenha2] = useState("");
  const [avatarFile, setAvatarFile] = useState(null);
  const [loading, setLoading] = useState(false);
  <Register setScreen={setScreen} setRegistering={setRegistering} />

  const cadastrar = async () => {
    if (!nome.trim()) return alert("Informe seu nome.");
    if (!email.trim()) return alert("Informe seu email.");
    if (senha.length < 6) return alert("Senha deve ter ao menos 6 caracteres.");
    if (senha !== senha2) return alert("Senhas não conferem.");

    setLoading(true);

    try {
      // 1) cria no Auth
      const userCred = await createUserWithEmailAndPassword(auth, email, senha);
      const user = userCred.user;
      const uid = user.uid;

      // 2) Upload avatar no SUPABASE
      let avatarUrl = "";
      if (avatarFile) {
        avatarUrl = await uploadAvatar(avatarFile, uid);
      }

      // 3) Atualizar perfil do Firebase Auth (display name + avatar)
      await updateProfile(user, {
        displayName: nome,
        photoURL: avatarUrl
      });

      // 4) Criar documento no Firestore
      await setDoc(doc(db, "users", uid), {
        id: uid,
        nome: nome.trim(),
        email: email.trim().toLowerCase(),
        avatarUrl: avatarUrl,
        online: false,
        createdAt: serverTimestamp()
      });

      // 5) logout
      await signOut(auth);
      alert("Conta criada com sucesso! Faça login.");
      setScreen("login");

    } catch (err) {
      console.error("ERRO NO REGISTER:", err);
      alert("Erro ao criar conta: " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <h2>Criar Conta</h2>

      <input placeholder="Nome" value={nome} onChange={e => setNome(e.target.value)} />
      <input placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
      <input placeholder="Senha" type="password" value={senha} onChange={e => setSenha(e.target.value)} />
      <input placeholder="Confirmar senha" type="password" value={senha2} onChange={e => setSenha2(e.target.value)} />

      <div style={{ marginTop: 8 }}>
        <label>Avatar (opcional)</label>
        <input type="file" accept="image/*" onChange={e => setAvatarFile(e.target.files[0] || null)} />
      </div>

      <button onClick={cadastrar} disabled={loading}>
        {loading ? "Criando..." : "Cadastrar"}
      </button>

      <p style={{ marginTop: 20, cursor: "pointer" }} onClick={() => setScreen("login")}>
        Voltar ao Login
      </p>
    </div>
  );
}
